40	  const { values } = parseArgs({
41	    args: Bun.argv.slice(2),
42	    options: { repo: { type: "string" }, issue: { type: "string" } },
43	  });
44	
45	  const repo = (values.repo ?? "").trim();
46	  const issue = Number(values.issue);
