190	export function ghPaginated<T = unknown>(...args: string[]): T[] {
191	  const { code, stdout, stderr } = gh(...args, "--paginate");
192	  if (code !== 0) {
193	    throw new Error(`gh ${args.join(" ")} --paginate: ${stderr || stdout}`);
194	  }
195	  if (!stdout.trim()) return [];
196	  const flat: T[] = [];
197	  for (const page of splitConcatenatedJson(stdout)) {
198	    if (Array.isArray(page)) flat.push(...(page as T[]));
199	  }
